{
  "headline": "Daptomycin is not on FDA's shortage list as of 2026-10-21; Corvale East has 7.9 days on hand and Corvale General has 18.3 days on hand",
  "headline_cites": ["D3", "D1", "D2"],
  "sentences": [
    {
      "text": "FDA's records show daptomycin is not on the drug shortage list as of 2026-10-21.",
      "cites": ["D3"]
    },
    {
      "text": "Corvale East holds 114 vials of daptomycin 350 mg/7 mL, 7 mL at 14.5 vials per day, providing 7.9 days on hand.",
      "cites": ["D1"]
    },
    {
      "text": "Corvale General holds 278 vials of the same presentation at 15.2 vials per day, providing 18.3 days on hand.",
      "cites": ["D2"]
    },
    {
      "text": "Both sites use product labeled by Meitheal Pharmaceuticals Inc. with NDC 71288001791 and SPL set ID 191f0224-67b7-4945-bdcd-38d60645e38c.",
      "cites": ["E1", "E2"]
    },
    {
      "text": "The label for that SPL set names Nanjing King-Friend Biochemical Pharmaceutical Co. as the manufacturing plant.",
      "cites": ["E3"]
    },
    {
      "text": "The top-ranked option by rule is to transfer 64 vials of 350 mg/7 mL, 7 mL from Corvale General to Corvale East, which would raise Corvale East to 12 days on hand while Corvale General retains two weeks of supply.",
      "cites": ["D4"]
    }
  ]
}
